"""Generates fixtures/numpy-rng-vectors.json, the known answers for norse_research.sim.pcg64.

Run once with real numpy, in a throwaway virtual environment outside the repository:

    /Users/lgreene/norse-worktrees/.venv-numpy-vectors/bin/python -I numpy-rng-vectors.py OUT

It is committed so the vectors can be regenerated and checked; nothing in the research
package imports numpy. The draws are the ones section 8 of docs/PREREGISTRATION.md
registers for the control runs: ``rng = numpy.random.default_rng(seed)``, C-H1's single
``rng.random(n) < 0.5`` (n is 158,821: the development daily bars of the 115 pinned
candidates in research/coverage/series-coverage.json) and C-H2's
``rng.integers(540, M - 540, endpoint=True)``, BTC drawn before ETH, with M = 6,576
development settlements for each coin.
"""

import hashlib
import json
import platform
import sys

import numpy as np

SEEDS = (0, 1, 42, 99)
C_H1_N = 158_821
DRAWS = 200_000  # covers C-H1's longest call
M = 6_576
SAMPLE = [*range(16), *range(10_000, DRAWS, 10_000), C_H1_N - 1, DRAWS - 1]
RANGES = [
    (540, M - 540, True),  # C-H2's call
    (0, 2**31 + 12_345, True),  # about half of Lemire's first draws are rejected
    (0, 2**32 - 1, True),  # the full 32-bit range: no rejection step
    (5, 5, True),  # one value: no draw at all
    (0, 10, False),  # the half-open default
    (-7, 3, True),  # negative bounds
]


def seed_words(seed):
    return [int(w) for w in np.random.SeedSequence(seed).generate_state(4, np.uint64)]


def vectors(seed):
    bit_generator = np.random.PCG64(seed)
    rng = np.random.default_rng(seed)
    doubles = rng.random(DRAWS)
    out = {
        "seed": seed,
        "seed_words": seed_words(seed),
        "next64": [int(bit_generator.random_raw()) for _ in range(8)],
        "random": {
            "draws": DRAWS,
            "sha256_float64_le": hashlib.sha256(doubles.astype("<f8").tobytes()).hexdigest(),
            "below_half_in_first_c_h1_n": int((doubles[:C_H1_N] < 0.5).sum()),
            "sample": {str(i): float(doubles[i]).hex() for i in SAMPLE},
        },
    }
    rng = np.random.default_rng(seed)
    out["c_h2_k"] = [int(rng.integers(540, M - 540, endpoint=True)) for _ in ("BTC", "ETH")]
    out["integers"] = []
    for low, high, endpoint in RANGES:
        rng = np.random.default_rng(seed)
        draws = [int(rng.integers(low, high, endpoint=endpoint)) for _ in range(64)]
        out["integers"].append({"low": low, "high": high, "endpoint": endpoint, "draws": draws})
    rng = np.random.default_rng(seed)
    mixed = [("integers", int(rng.integers(0, 1000)))]
    mixed += [("random", float(x).hex()) for x in rng.random(3)]
    mixed += [("integers", int(rng.integers(0, 1000))), ("integers", int(rng.integers(0, 1000)))]
    mixed += [("random", float(rng.random()).hex())]
    out["mixed"] = mixed
    return out


def main():
    document = {
        "about": "Known answers for norse_research.sim.pcg64, generated by numpy-rng-vectors.py",
        "numpy_version": np.__version__,
        "python_version": platform.python_version(),
        "platform": f"{sys.platform} {platform.machine()}",
        "c_h1_n": C_H1_N,
        "development_settlements_m": M,
        "seeds": [vectors(seed) for seed in SEEDS],
    }
    with open(sys.argv[1], "w") as handle:
        json.dump(document, handle, indent=1)
        handle.write("\n")


if __name__ == "__main__":
    main()
